{
  "decision-split-an-ordered-label-run": "WITH neighbors AS (SELECT b.*, w.source_id, w.wash_min, LAG(ink_code) OVER (ORDER BY batch_no) AS prev_ink, LEAD(ink_code) OVER (ORDER BY batch_no) AS next_ink FROM label_batches AS b CROSS JOIN wash_card AS w), splits AS (SELECT batch_no AS last_west_batch, SUM(west_min + CASE WHEN ink_code <> prev_ink THEN wash_min ELSE 0 END) OVER (ORDER BY batch_no ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS west_minutes, SUM(east_min + CASE WHEN ink_code <> next_ink THEN wash_min ELSE 0 END) OVER (ORDER BY batch_no ROWS BETWEEN 1 FOLLOWING AND UNBOUNDED FOLLOWING) AS east_minutes, source_id FROM neighbors) SELECT last_west_batch, west_minutes, east_minutes, MAX(west_minutes, east_minutes) AS finish_minutes, source_id FROM splits WHERE east_minutes IS NOT NULL ORDER BY finish_minutes, last_west_batch LIMIT 1",
  "decision-split-irregular-equipment-loan-payments": "WITH payments AS (SELECT loan_id, remitted_cents, MIN(remitted_cents, opening_interest + (opening_principal * annual_bp * elapsed_days + 1800000) / 3600000) AS operating_interest_cents FROM loan_remit) SELECT loan_id, operating_interest_cents, remitted_cents - operating_interest_cents AS financing_principal_cents FROM payments ORDER BY loan_id",
  "decision-split-reading-kits-between-branches": "WITH splits AS (SELECT d.alder_qty AS alder_kits, s.available_kits - d.alder_qty AS birch_kits FROM dispatch_option AS d CROSS JOIN stockroom AS s) SELECT s.alder_kits, s.birch_kits, MIN(100 * (a.covered_classes + s.alder_kits) / a.class_count, 100 * (b.covered_classes + s.birch_kits) / b.class_count) AS floor_coverage_pct, s.alder_kits * a.kit_shipping_cents + s.birch_kits * b.kit_shipping_cents AS shipping_cents FROM splits AS s JOIN branch_program AS a ON a.branch_code = 'alder' JOIN branch_program AS b ON b.branch_code = 'birch' WHERE s.alder_kits BETWEEN 0 AND a.class_count - a.covered_classes AND s.birch_kits BETWEEN 0 AND b.class_count - b.covered_classes ORDER BY floor_coverage_pct DESC, shipping_cents, s.alder_kits LIMIT 1",
  "decision-staff-a-serial-carton-line": "WITH crew(n) AS (VALUES (1), (2), (3), (4)), allocations AS (SELECT f.n AS fold_crew, t.n AS trim_crew, s.operators - f.n - t.n AS pack_crew, s.source_id FROM shift_ticket AS s CROSS JOIN crew AS f CROSS JOIN crew AS t) SELECT a.fold_crew, a.trim_crew, a.pack_crew, MIN(a.fold_crew * f.rate_per_hour, a.trim_crew * t.rate_per_hour, a.pack_crew * p.rate_per_hour) AS cartons_per_hour, a.source_id FROM allocations AS a JOIN machine_rates AS f ON f.machine_code = 'fold' JOIN machine_rates AS t ON t.machine_code = 'trim' JOIN machine_rates AS p ON p.machine_code = 'pack' WHERE a.pack_crew BETWEEN 1 AND 4 ORDER BY cartons_per_hour DESC, a.fold_crew, a.trim_crew LIMIT 1"
}
